parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "feature_id": {
      "type": "integer",
      "description": "Id of the feature: the number of the 'ID:' line right after the '# ' heading."
    },
    "stories": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "story_id": {
            "type": [
              "integer",
              "null"
            ],
            "description": "Id of an existing story (number of its 'ID:' line); null for a new story (its line is 'Priorité:')."
          },
          "title": {
            "type": "string"
          },
          "priority": {
            "type": [
              "string",
              "null"
            ],
            "description": "Value of the 'Priorité:' line of a new story, verbatim; null for an existing story."
          },
          "description": {
            "type": "string"
          }
        },
        "required": [
          "story_id",
          "title",
          "priority",
          "description"
        ]
      }
    }
  },
  "required": [
    "feature_id",
    "stories"
  ]
}

parameters.jsonBody:
={{ {
  type: 'page',
  title: $('Parsing agent').first().json.output.project_name + ' - Definition of Ready',
  space: { key: $('Parsing agent').first().json.output.confluence_space_key },
  body: { storage: { value: $json.data, representation: 'storage' } }
} }}

parameters.jsonSchemaExample:
{
